{
  "title": "不超过 20 字的内容标题（能一眼看出讲的是什么）",
  "summary": "3-6 句话的摘要，说清背景、主要内容和结论",
  "key_points": [{"point": "关键点（一句话）", "evidence": "支撑该点的原文关键句，不超过 60 字"}],
  "todos": [{"task": "待办事项", "owner": "负责人或空字符串", "due": "时间要求或空字符串"}],
  "decisions": ["已达成的决定/结论"],
  "open_questions": ["尚未解决的问题"],
  "keywords": ["3-8 个关键词"]
}
